module sequence_detector(
    input clk, 
    input reset_n, 
    input data_in,
    output sequence_detected
);
    reg [2:0] current_state, next_state;
    localparam IDLE = 3'b000, S1 = 3'b001, S2 = 3'b010, S3 = 3'b011, S4 = 3'b100;
    always @(posedge clk or negedge reset_n) begin
        if(!reset_n)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case(current_state)
            IDLE: begin
                if(data_in==1'b1)
                    next_state = S1;
                else
                    next_state = IDLE;
            end

            S1: begin
                if(data_in==1'b0)
                    next_state = S2;
                else
                    next_state = S1;
            end

            S2: begin
                if(data_in==1'b0)
                    next_state = S3;
                else
                    next_state = S1;
            end

            S3: begin
                if(data_in==1'b1)
                    next_state = S4;
                else
                    next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    assign sequence_detected = (current_state==S4);

endmodule
